#!/usr/bin/env bash
# Fixes the real crash loop just observed live on Ewan: exit code 2
# ("can't open file 'run.py'") repeating every few seconds right after
# agent startup.
#
# Root cause: when a rollback has nothing to restore TO (the very first
# install on a machine — there is no previous version, so
# restore_recovery_point correctly recreates app_install_dir but leaves it
# EMPTY), the previously-persisted kiosk_start_command was left in place
# unchanged, still pointing at a run.py that no longer exists. Every agent
# restart (or the watchdog's own retry loop) then tried to launch it,
# failed immediately, retried, failed again — burning through the crash
# budget in about 20 seconds — with nothing to break the cycle until a
# future update happened to install successfully.
#
# Fixed in agent/update_manager.py::_attempt_rollback: when
# restore_recovery_point reports had_app=False (nothing existed before
# this deployment), the kiosk configuration (start command, working dir,
# health check URL/command) is now explicitly cleared and persisted, and
# the supervisor is stopped and unconfigured — instead of leaving a
# guaranteed-broken command in place. Once a future update installs
# successfully, _auto_default_kiosk_command (already in place from an
# earlier fix) configures it fresh, exactly as it would for a genuinely
# first-time install. The case where a REAL previous version exists and
# gets restored is completely untouched by this change.
#
# Verified against a real reproduction of Ewan's exact scenario: a
# recovery point with had_app=False, a stale kiosk_start_command already
# persisted, then _attempt_rollback called with a failing health check —
# confirmed the supervisor is stopped/unconfigured, settings.json is
# rewritten with everything cleared, and app_install_dir really is empty
# afterward (matching what install.ps1 console output showed). Separately
# verified the had_app=True path (a real previous version) is completely
# unaffected — config stays intact, files are correctly restored.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in agent requirements.txt service_files; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

echo "==> Extracting fixed agent/ into this repo"
TMP_EXTRACT="$(mktemp -d)"
base64 -d > "$TMP_EXTRACT/opslab-agent.tar.gz" << 'AGENT_TAR_EOF_MARKER'

AGENT_TAR_EOF_MARKER
tar -xzf "$TMP_EXTRACT/opslab-agent.tar.gz" -C "$TMP_EXTRACT"

if ! grep -q "_clear_kiosk_configuration" "$TMP_EXTRACT/agent/update_manager.py"; then
    echo "    ERROR: fix not found in the extracted agent payload!"
    rm -rf "$TMP_EXTRACT"
    exit 1
fi

rm -f agent/config.py.bak
cp -f "$TMP_EXTRACT/agent/"*.py agent/
echo "    Updated agent/*.py in this repo."

echo "==> Rewriting app/static/installers/opslab-agent.tar.gz (served by /install.ps1)"
cp -f "$TMP_EXTRACT/opslab-agent.tar.gz" app/static/installers/opslab-agent.tar.gz
rm -rf "$TMP_EXTRACT"

echo "==> Verifying"
tar -tzf app/static/installers/opslab-agent.tar.gz > /dev/null && echo "    served agent tarball is readable"

echo ""
echo "Done. This only affects Agent code, no admin panel restart needed - but"
echo "Ewan itself needs the FIXED agent, which means re-enrolling (or waiting for"
echo "a self-update, but Ewan currently has nothing successfully installed to"
echo "self-update FROM). Simplest path: on Ewan, stop the current console session"
echo "(Ctrl+C) if still running, then re-run the same enrollment command to pull"
echo "the fixed agent fresh:"
echo "    irm https://kiosksys.opslabsystems.cloud/install.ps1 -OutFile install.ps1; .\\install.ps1 -Token <fresh-token> -AdminUrl https://kiosksys.opslabsystems.cloud"
echo ""
echo "After that, push v1.0.1 again (the earlier stuck-deployment fix means this"
echo "works immediately, no waiting) - this time nothing will crash-loop even if"
echo "something goes wrong, and a real success will auto-configure and start cleanly."
